"""battle_text: the battle message window, its page journal and the battle wait.

The fixture is read-only raw RAM from the showcase run
2026-10-16T00-34-26_qwen36-gpu1_show (raw-ram 7765-7835), cut to the addresses
the reader uses (generated by a scratch script over pokebench_env.raw_ram).
"""

import json
import struct
import threading
import types
from contextlib import nullcontext
from pathlib import Path

import pytest
from fastapi import FastAPI
from test_view import get

from pokebench_env import battle_text as bt
from pokebench_env.battle_state import read_battle_state
from pokebench_env.gba_text import GBA_TEXT

FIXTURE = json.loads((Path(__file__).parent / "fixtures/battle-text-show-7765.json").read_text())
ENCODE = {char: code for code, char in GBA_TEXT.items()}


class Archived:
    def __init__(self, memory: dict[str, str]) -> None:
        self.regions = {int(k, 16): bytes.fromhex(v) for k, v in memory.items()}

    def read(self, address: int, length: int) -> bytes:
        for base, data in self.regions.items():
            if base <= address and address + length <= base + len(data):
                return data[address - base : address - base + length]
        raise ValueError(f"outside fixture: {address:#x}")


def frame(name: str) -> Archived:
    return Archived(next(f["memory"] for f in FIXTURE["frames"] if f["raw_ram"] == name))


def encode(text: str) -> bytes:
    return bytes(ENCODE[c] for c in text)


class Memory:
    """Independent synthetic layout (pret include/text.h, battle_main.c)."""

    def __init__(self) -> None:
        self.data: dict[int, int] = {}
        self.set(0x030026F9, 2, 1)
        self.set(0x030022C4, 0x08038421)

    def put(self, address: int, value: bytes) -> None:
        self.data.update({address + i: b for i, b in enumerate(value)})

    def set(self, address: int, value: int, size: int = 4) -> None:
        self.put(address, value.to_bytes(size, "little"))

    def read(self, address: int, length: int) -> bytes:
        return bytes(self.data.get(address + i, 0) for i in range(length))

    def message(self, raw: bytes, cursor: int, state: int = 0, window: int = 0) -> None:
        self.put(0x02022E2C, raw + bytes(300 - len(raw)))
        self.set(0x020201B0, 0x02022E2C + cursor)
        self.set(0x020201B0 + 4, window, 1)
        self.set(0x020201B0 + 0x1B, 1, 1)
        self.set(0x020201B0 + 0x1C, state, 1)

    def idle(self) -> None:
        self.set(0x020201B0 + 0x1B, 0, 1)


def test_real_ram_healthbox_name_in_the_buffer_is_not_a_message() -> None:
    """raw-ram 7765: gDisplayedStringBattle holds the healthbox name; printer 0 is idle."""
    memory = frame("00007765.json.gz")
    assert "WURMPLE" in bt.decode_battle_text(
        memory.read(0x02022E2C, 300)[: memory.read(0x02022E2C, 300).index(0xFF)]
    )
    assert bt.read_battle_message(memory.read) == bt.BattleMessage("idle")
    assert bt.battle_text_phase(memory.read) == "busy"


def test_real_ram_waiting_printing_idle_input_and_field() -> None:
    waiting = bt.read_battle_message(frame("00007772.json.gz").read)
    assert (waiting.state, waiting.render_state, waiting.text, waiting.cursor) == (
        "waiting_for_input",
        "page_wait",
        "Wild WURMPLE appeared!\n",
        23,
    )
    assert bt.wait_phase(frame("00007772.json.gz").read) == "message_waiting"
    printing = bt.read_battle_message(frame("00007790.json.gz").read)
    assert printing.state == "printing" and printing.text == " ,VQ  SOC  used\nSCRATCH!"
    assert bt.wait_phase(frame("00007790.json.gz").read) == "busy"
    assert bt.read_battle_message(frame("00007782.json.gz").read).state == "idle"
    assert bt.wait_phase(frame("00007782.json.gz").read) == "input"
    assert bt.wait_phase(frame("00007834.json.gz").read) == "busy"  # field return callback
    assert bt.wait_phase(frame("00007835.json.gz").read) == "field"


def test_real_ram_journal_pages_whole_and_in_order() -> None:
    journal = bt.BattleTextJournal(clock=lambda: 1.5)
    for item in FIXTURE["frames"]:
        journal.advance(Archived(item["memory"]).read)
    snap = journal.snapshot(0)
    assert snap["errors"] == 0
    pages = [(e["text"], e["waited_for_input"], e["battle"]) for e in snap["entries"]]  # type: ignore[attr-defined]
    assert pages == [
        ("Wild WURMPLE appeared!", True, 1),
        (",VQ  SOC  used\nSCRATCH!", False, 1),
        ("Wild WURMPLE\nfainted!", True, 1),
        (",VQ  SOC  gained\n15 EXP. Points!", True, 1),
    ]
    assert snap["entries"][0]["recorded_ms"] == 1500  # type: ignore[index]
    assert journal.snapshot(4)["entries"] == []


def battle_with_real_message():  # type: ignore[no-untyped-def]
    """test_battle_state's synthetic battle with raw-ram 7772's printer, buffer and callbacks."""
    from test_battle_state import fixture

    memory = fixture()
    real = frame("00007772.json.gz")
    for address, length in (
        (0x020201B0, 0x24),
        (0x03003014, 1),
        (0x02022E2C, 300),
        (0x030022C0, 8),
    ):
        memory.put(address, real.read(address, length))
    memory.put(0x02024068, b"\x00\x00\x00\x00")  # no input owner busy: the message is what waits
    return memory


def test_battle_state_carries_the_message_prompt_and_phase() -> None:
    state = read_battle_state(battle_with_real_message().read)
    assert state.message is not None and state.message.text == "Wild WURMPLE appeared!\n"
    assert state.text_phase == "message_waiting" and state.prompt is None
    assert state.json()["message"]["state"] == "waiting_for_input"  # type: ignore[index]


def test_battle_state_keeps_a_text_read_failure_local() -> None:
    memory = battle_with_real_message()

    def failing(address: int, length: int) -> bytes:
        if address == 0x020201B0:
            raise ValueError("printer unreadable")
        return memory.read(address, length)

    state = read_battle_state(failing)
    assert state.phase != "unavailable"
    assert state.message == bt.BattleMessage(
        "idle", diagnostic="harness bug: battle text: printer unreadable"
    )
    assert state.text_phase is None


def test_printer_must_be_window_zero_on_the_buffer() -> None:
    memory = Memory()
    memory.message(encode("Hello") + b"\xfa\xff", 6, state=2, window=1)
    assert bt.read_battle_message(memory.read).state == "idle"
    memory.message(encode("Hello") + b"\xfa\xff", 6, state=2)
    memory.set(0x020201B0, 0x02022E2C + 301)
    assert bt.read_battle_message(memory.read).state == "idle"


def test_healthbox_overwrite_under_an_active_printer_is_a_diagnostic_not_text() -> None:
    memory = Memory()
    memory.message(encode("ZIGZAGOON") + b"\xff", 40, state=0)
    message = bt.read_battle_message(memory.read)
    assert message.text is None and message.state == "printing"
    assert message.diagnostic == (
        "harness bug: battle text: printer cursor is past the message's end"
    )


def test_unknown_render_state_and_auto_scroll() -> None:
    memory = Memory()
    memory.message(encode("Hi") + b"\xfa\xff", 3, state=9)
    message = bt.read_battle_message(memory.read)
    assert message.diagnostic == "harness bug: battle text: unknown text printer state 9"
    memory.message(encode("Hi") + b"\xfa\xff", 3, state=2)
    memory.set(0x03003014, bt.AUTO_SCROLL, 1)
    assert bt.read_battle_message(memory.read).state == "printing"
    assert bt.battle_text_phase(memory.read) == "busy"


@pytest.mark.parametrize(
    ("opcode", "kind", "learning"),
    [
        (0x5A, "learn_move", True),
        (0x5B, "stop_learning_move", True),
        (0x67, "yes_no", False),
        (0xF3, "nickname_caught", False),
    ],
)
def test_battle_script_yes_no_prompts(opcode: int, kind: str, learning: bool) -> None:
    memory = Memory()
    memory.set(0x03005D04, 0x0803E08D)
    memory.set(0x02024214, 0x082D9000)
    memory.put(0x082D9000, bytes([opcode]))
    assert bt.read_battle_prompt(memory.read) == bt.BattlePrompt(kind, False, None)
    memory.set(0x02024474 + 0x1F if learning else 0x02024332, 1, 1)
    memory.set(0x02024333, 1, 1)
    assert bt.read_battle_prompt(memory.read) == bt.BattlePrompt(kind, True, "NO")
    assert bt.battle_text_phase(memory.read) == "prompt"
    memory.set(0x02024333, 0, 1)
    assert bt.read_battle_prompt(memory.read) == bt.BattlePrompt(kind, True, "YES")


def test_prompt_needs_a_script_owner_a_rom_pc_and_a_yes_no_opcode() -> None:
    memory = Memory()
    assert bt.read_battle_prompt(memory.read) is None
    memory.set(0x03005D04, 0x0803E019)
    assert bt.read_battle_prompt(memory.read) is None
    memory.set(0x02024214, 0x082D9000)
    memory.put(0x082D9000, b"\x10")
    assert bt.read_battle_prompt(memory.read) is None


def test_input_ready_only_for_a_player_bank_with_an_input_owner() -> None:
    memory = Memory()
    assert bt.battle_input_ready(memory.read) is False
    memory.set(0x0202406C, 2, 1)
    memory.put(0x02024076, bytes([0, 1]))
    memory.set(0x03005D60, 0x08057589)
    assert bt.battle_input_ready(memory.read) is False
    memory.set(0x02024068, 2)
    assert bt.battle_input_ready(memory.read) is False
    memory.set(0x02024068, 1)
    assert bt.battle_input_ready(memory.read) is True
    assert bt.battle_text_phase(memory.read) == "input"


def test_phases_off_the_battle_screen() -> None:
    memory = Memory()
    memory.set(0x030022C4, 0x08036FAD)
    assert bt.battle_text_phase(memory.read) == "busy"
    memory.set(0x030022C4, 0x081AAD5D)
    assert bt.battle_text_phase(memory.read) == "screen"
    assert bt.wait_phase(memory.read) == "screen"
    memory.set(0x030026F9, 0, 1)
    assert bt.wait_phase(memory.read) == "busy", "not in battle, not yet the field"
    for callback in (0x080B11A9, 0x08085E51, 0x080861CD, 0x08085F59):
        memory.set(0x030022C4, callback)
        assert bt.wait_phase(memory.read) == "busy"
    memory.set(0x030022C4, 0x08085E5D)
    assert bt.wait_phase(memory.read) == "field"
    memory.set(0x02037FD4 + 7, 0x80, 1)
    assert bt.wait_phase(memory.read) == "busy", "the field is still fading in"


def test_short_reads_raise() -> None:
    with pytest.raises(ValueError, match="short battle text read"):
        bt.read_battle_message(lambda address, length: b"")


def test_journal_cuts_pages_at_each_wait_and_closes_a_finished_message() -> None:
    memory = Memory()
    raw = (
        encode("Wild POOCHYENA")
        + b"\xfe"
        + encode("appeared!")
        + b"\xfa"
        + encode("Go! MUDKIP!")
        + b"\xff"
    )
    journal = bt.BattleTextJournal(clock=lambda: 0)
    memory.message(raw, 3)
    journal.advance(memory.read)
    memory.message(raw, 25, state=2)
    journal.advance(memory.read)
    journal.advance(memory.read)  # still waiting: no second page
    memory.message(raw, 30, state=0)
    journal.advance(memory.read)
    memory.idle()
    journal.advance(memory.read)
    entries = journal.snapshot(0)["entries"]
    assert [(e["text"], e["waited_for_input"]) for e in entries] == [  # type: ignore[attr-defined]
        ("Wild POOCHYENA\nappeared!", True),
        ("Go! MUDKIP!", False),
    ]


def test_journal_back_to_back_messages_and_restarts() -> None:
    memory = Memory()
    journal = bt.BattleTextJournal(clock=lambda: 0)
    memory.message(encode("A used TACKLE!") + b"\xff", 5)
    journal.advance(memory.read)
    memory.message(encode("It's super effective!") + b"\xff", 9)
    journal.advance(memory.read)
    memory.message(encode("It's super effective!") + b"\xff", 2)
    journal.advance(memory.read)
    memory.set(0x030022C4, 0x081AAD5D)  # the bag opened: the message window is not shown
    journal.advance(memory.read)
    texts = [e["text"] for e in journal.snapshot(0)["entries"]]  # type: ignore[attr-defined]
    assert texts == ["A used TACKLE!", "It's super effective!", "It's super effective!"]


def test_journal_counts_battles_skips_empty_pages_and_bounds_the_ring() -> None:
    memory = Memory()
    journal = bt.BattleTextJournal(capacity=2, clock=lambda: 0)
    for text in ("One", "Two", "Three"):
        memory.message(encode(text) + b"\xfa\xff", len(text) + 1, state=2)
        journal.advance(memory.read)
        memory.idle()
        journal.advance(memory.read)
    memory.set(0x030026F9, 0, 1)
    journal.advance(memory.read)
    memory.set(0x030026F9, 2, 1)
    memory.message(b"\xfa\xff", 1, state=2)
    journal.advance(memory.read)
    snap = journal.snapshot(1)
    assert (snap["first_id"], snap["last_id"]) == (2, 3)
    assert [(e["text"], e["battle"]) for e in snap["entries"]] == [("Two", 1), ("Three", 1)]  # type: ignore[attr-defined]
    assert journal.battle == 2
    with pytest.raises(ValueError, match="cursor out of range"):
        journal.snapshot(4)
    assert bt.BattleTextJournal().snapshot(0)["first_id"] == 1


def test_journal_records_a_decoder_failure_and_keeps_going() -> None:
    memory = Memory()
    journal = bt.BattleTextJournal(clock=lambda: 0)
    memory.message(b"\xf7\xff", 1)
    journal.advance(memory.read)
    snap = journal.snapshot(0)
    assert snap["errors"] == 1 and str(snap["last_error"]).startswith(
        "harness bug: battle text journal:"
    )
    memory.message(encode("Hi") + b"\xff", 40)
    journal.advance(memory.read)
    assert journal.snapshot(0)["errors"] == 2
    memory.message(encode("Hi") + b"\xff", 1)
    journal.advance(memory.read)
    memory.idle()
    journal.advance(memory.read)
    assert [e["text"] for e in journal.snapshot(0)["entries"]] == ["Hi"]  # type: ignore[attr-defined]


def test_messages_route_and_frame_hook() -> None:
    memory = Memory()
    app = FastAPI()

    class Emulator:
        def run_frame_with_buttons(self, buttons: list[str]) -> None:
            pass

    journal = bt.install_battle_text(app, Emulator, memory.read)
    memory.message(encode("Hello") + b"\xfa\xff", 6, state=2)
    Emulator().run_frame_with_buttons([])
    assert journal.frame == 1
    status, _, body = get(app, "/pokebench/battle/messages", b"after=0")
    assert status == 200 and json.loads(body)["entries"][0]["text"] == "Hello"
    status, _, _ = get(app, "/pokebench/battle/messages", b"after=9")
    assert status == 409


def wait_in_thread(wait: bt.BattleWait, capture, bound: int = 600):  # type: ignore[no-untyped-def]
    result: dict[str, object] = {}

    def target() -> None:
        try:
            result["r"] = wait.wait(capture, nullcontext(), bound)
        except RuntimeError as error:
            result["error"] = str(error)

    thread = threading.Thread(target=target, daemon=True)
    thread.start()
    return thread, result


def test_wait_returns_on_the_first_frame_the_battle_needs_input() -> None:
    memory = Memory()
    wait = bt.BattleWait(memory.read)
    wait.on_frame()  # no waiters: nothing to do
    thread, result = wait_in_thread(wait, lambda: "captured")
    thread.join(0.2)
    assert thread.is_alive()
    wait.on_frame()
    thread.join(0.1)
    assert thread.is_alive()
    memory.message(encode("Hi") + b"\xfa\xff", 3, state=2)
    wait.on_frame()
    thread.join(5)
    assert result["r"] == ("captured", "message_waiting", 2)
    assert wait.wait(lambda: "now", nullcontext()) == ("now", "message_waiting", 0)


def test_wait_bound_capture_error_and_read_error() -> None:
    memory = Memory()
    wait = bt.BattleWait(memory.read)
    thread, result = wait_in_thread(wait, lambda: "late", bound=2)
    thread.join(0.1)
    wait.on_frame()
    wait.on_frame()
    thread.join(5)
    assert result["r"] == ("late", "bound", 2)

    def boom() -> str:
        raise RuntimeError("capture failed")

    thread, result = wait_in_thread(wait, boom, bound=1)
    thread.join(0.1)
    wait.on_frame()
    thread.join(5)
    assert result == {"error": "capture failed"}

    broken = {"fail": False}

    def read(address: int, length: int) -> bytes:
        if broken["fail"]:
            return b""
        return memory.read(address, length)

    failing = bt.BattleWait(read)
    errors: list[BaseException] = []

    def run() -> None:
        try:
            failing.wait(lambda: "x", nullcontext())
        except ValueError as error:
            errors.append(error)

    thread = threading.Thread(target=run, daemon=True)
    thread.start()
    thread.join(0.1)
    broken["fail"] = True
    failing.on_frame()
    thread.join(5)
    assert [str(e) for e in errors] == ["short battle text read"]


def test_wait_parks_and_resumes_with_the_frame_loop() -> None:
    memory = Memory()
    wait = bt.BattleWait(memory.read)
    thread, result = wait_in_thread(wait, lambda: "held")
    thread.join(0.1)
    wait.park()
    thread.join(5)
    assert result["r"] == ("held", "paused", 0)
    assert wait.wait(lambda: "x", nullcontext()) == ("x", "paused", 0)
    wait.resume()
    thread, result = wait_in_thread(wait, lambda: "after")
    thread.join(0.1)
    assert thread.is_alive()
    memory.set(0x030026F9, 0, 1)
    memory.set(0x030022C4, 0x08085E5D)
    wait.on_frame()
    thread.join(5)
    assert result["r"] == ("after", "field", 1)


def test_wait_route_through_the_observation_and_the_production_run() -> None:
    from test_observation import Shot

    from pokebench_env.game_state import MapNames
    from pokebench_env.serve import run

    memory = Memory()
    memory.set(0x030026F9, 0, 1)
    memory.set(0x030022C4, 0x08085E5D)
    lock = threading.Lock()
    app = FastAPI()
    module = types.SimpleNamespace(step_environment=lambda actions: None)

    class Emulator:
        def run_frame_with_buttons(self, buttons: list[str]) -> None:
            pass

    run(
        [],
        uvicorn=types.SimpleNamespace(run=lambda *a, **k: None),
        vendor_main=lambda: None,
        observation=(app, Shot, memory.read, MapNames({}), lock),
        pause=(app, module),
        frames=Emulator,
        battle_text=(app, Emulator, memory.read),
    )
    status, _, body = get(app, "/pokebench/battle/wait")
    payload = json.loads(body)
    assert status == 200 and (payload["reason"], payload["frames"]) == ("field", 0)
    assert payload["state"]["in_battle"] is False
    memory.set(0x030026F9, 2, 1)
    memory.set(0x030022C4, 0x08038421)
    result: dict[str, object] = {}
    thread = threading.Thread(
        target=lambda: result.update(r=get(app, "/pokebench/battle/wait", b"max_frames=3")),
        daemon=True,
    )
    thread.start()
    thread.join(0.2)
    assert thread.is_alive()
    for _ in range(3):
        with lock:
            Emulator().run_frame_with_buttons([])
    thread.join(5)
    assert json.loads(result["r"][2])["reason"] == "bound"  # type: ignore[index]
    assert get(app, "/pokebench/battle/messages")[0] == 200
    assert get(app, "/pokebench/battle/wait", b"max_frames=0")[0] == 422


